mapper.select:
select * from ( SELECT a.*, b.MACHINE_NAME FROM T_CD90_QUOTA_SETTING a LEFT JOIN T_CD90_MACHINE_INFO b ON a.MACHINE_ID = b.ID WHERE a.del_flag = '0'
and INSTR(cloth_code, #{clothCode,jdbcType=VARCHAR}) > 0
and a.machine_id = #{machineId} and a.quota = #{quota}
order by a.CREATE_TIME desc
) t
order by ${orderStr}


where del_flag = '0'
and id != #{id}
and machine_id is null
and machine_id = #{machineId,jdbcType=DECIMAL}
and cloth_code is null
and cloth_code = #{clothCode,jdbcType=VARCHAR}

mapper.update:
merge into T_CD90_QUOTA_SETTING a USING (
select #{QuotaSetting.clothCode,jdbcType=VARCHAR} CLOTH_CODE, #{QuotaSetting.machineId,jdbcType=DOUBLE} machine_id, #{QuotaSetting.quota,jdbcType=DOUBLE} quota, #{QuotaSetting.createBy,jdbcType=VARCHAR} create_by, #{QuotaSetting.createTime,jdbcType=DATE} create_time, #{QuotaSetting.updateBy,jdbcType=VARCHAR} update_by, #{QuotaSetting.updateTime,jdbcType=DATE} update_time, #{QuotaSetting.remark,jdbcType=VARCHAR} remark from dual
) b ON ( ((b.CLOTH_CODE is null and a.CLOTH_CODE is null) or (a.CLOTH_CODE = b.CLOTH_CODE)) and ((b.machine_id is null and a.machine_id is null) or(b.machine_id = a.machine_id)) AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.quota = b.quota, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT (a.id, a.CLOTH_CODE, a.machine_id, a.quota, a.create_by, a.create_time, a.remark, a.del_flag) values (SEQ_QUOTA_SETTING.NEXTVAL, b.CLOTH_CODE, b.machine_id, b.quota, b.create_by, sysdate, b.remark, '0')
